/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function deallocates a previously allocated object.            */
/*    Before releasing the backing memory to the object pool, the         */
/*    function inspects the object's ID field.  If the memory still       */
/*    backs a live ThreadX kernel object (timer, thread, semaphore,       */
/*    mutex, queue, event flags group, block pool, or byte pool) the      */
/*    appropriate tx_*_delete() service is called first to remove the     */
/*    object from all kernel-internal lists and release any associated    */
/*    runtime state.  This prevents use-after-free in kernel paths such   */
/*    as the timer expiration trampoline.                                 */
/*                                                                        */
/*    When TXM_MODULE_OBJECT_DEALLOC_STRICT is defined the function       */
/*    returns TX_DELETE_ERROR to signal that a live object was detected   */
/*    and cleaned up automatically.  Without that define the cleanup is   */
/*    silent and TX_SUCCESS is returned (backward-compatible default).    */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    object_ptr                        Object pointer to deallocate      */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    TX_SUCCESS                        Object was already cleaned up     */
/*                                        (or was never a live kernel     */
/*                                        object) - pool memory freed     */
/*    TX_DELETE_ERROR                   A live kernel object was found    */
/*                                        and cleaned up automatically    */
/*                                        (only when                      */
/*                                        TXM_MODULE_OBJECT_DEALLOC_STRICT*/
/*                                        is defined)                     */
/*    TX_PTR_ERROR                      Invalid object pointer            */
/*    TX_NOT_AVAILABLE                  Object pool not created           */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    _txe_mutex_get                        Get module instance mutex     */
/*    _txe_mutex_put                        Release module instance mutex */
/*    _txe_byte_release                     Release object back to pool   */
/*    _tx_timer_delete                      Delete live timer             */
/*    _tx_thread_terminate                  Terminate live thread         */
/*    _tx_thread_delete                     Delete live thread            */
/*    _tx_semaphore_delete                  Delete live semaphore         */
/*    _tx_mutex_delete                      Delete live mutex             */
/*    _tx_queue_delete                      Delete live queue             */
/*    _tx_event_flags_delete                Delete live event flags group */
/*    _tx_block_pool_delete                 Delete live block pool        */
/*    _tx_byte_pool_delete                  Delete live byte pool         */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    Application code                                                    */
/*                                                                        */
